    'on error errStr',
    'try',
    'close access imgFile',
    'end try',
    'error errStr',
    'end try',
  ];
  final result = await runner('osascript', [
    for (final line in script) ...['-e', line],
  ]);
  if (result.exitCode != 0) return null;
  try {
    final bytes = File(target).readAsBytesSync();
    File(target).deleteSync();
    return bytes;
  } on Object {
    return null;
  }
}

