/// it into the named unavailable result the transcript prints as a clean
/// note (edge E1).
Future<PasteboardRead> _readPlatform(
  ProcessRunner run,
  Directory tmp,
  String? platform,
) async {
  try {
    switch (_effectivePlatform(platform)) {
